fn choose_num(x: i8, y: i8) -> i8 {
    // If the lower bound exceeds the upper bound, no valid interval.
    if x > y {
        return -1;
    }

    // Compute the largest even number ≤ y.
    // If y is even, that's y; otherwise it's y - 1.
    let candidate = if y % 2 == 0 { y } else { y - 1 };

    // If that even candidate lies below the lower bound, there is no even
    // number in [x, y].
    if candidate < x {
        -1
    } else {
        candidate
    }
}

